  l.ground_color = Vec3{0.025, 0.026, 0.04} * night;
  l.fog_color = mix3(mix3({0.474, 0.584, 0.716}, {0.62, 0.45, 0.36}, dusk * 0.6), {0.03, 0.04, 0.07}, night);
